# define	EXTERN# include	"inews.h"intmain (argc, argv)int argc;char *argv[];{	zero_out ();	parse_args (argc, argv);	if (do_init (TRUE) < 0) {		do_log ("Failed in do_init()\n");		do_exit (1);	}	if (read_active () < 0) {		do_log ("Failed in read_active()\n");		do_exit (1);	}	if (read_sys () < 0) {		do_log ("Failed in read_sys()\n");		do_exit (1);	}	if (read_header (0) < 0) {		do_log ("Failed in read_header()\n");		do_exit (1);	}	if (check_active () < 0) {		do_log ("Failed in check_active()\n");		do_exit (1);	}	if (write_groups () < 0) {		do_log ("Failed in write_groups()\n");		do_exit (1);	}	if (process_sys () < 0) {		do_log ("Failed in process_sys()\n");		do_exit (1);	}	if (restore_active () < 0) {		do_log ("Failed in restore_active()\n");		do_exit (1);	}	do_exit (0);}